-- psionic_powers rows that existed only in production.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/restore-psionics-missing-from-repo.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/restore-psionics-missing-from-repo.sql
--
-- WHY THESE WERE MISSING. The catalog editor and the importer's confirm step
-- both write straight to D1. Nothing in git creates what they add, so a
-- database built from schema.sql plus the data scripts came up 36 psionic_powers
-- rows short, and every class citing one had a dead reference.
--
-- Found by a regression test, not by inspection: an audit of every only/except
-- restriction failed against a fresh build because it named skills that build
-- did not have. The same gap had already been found once for classes
-- (chiang-ku-dragon and juicer) and closed the same way.
--
-- NAMED restore-* DELIBERATELY. Data scripts are applied in filename order, and
-- an add-* file would sort BEFORE rename-skills-to-rue.sql: the restore would
-- insert Mathematics: Basic, the rename would then find its target name already
-- taken and skip, and a fresh build would end up holding BOTH that and the
-- Basic Math the seed created. restore-* sorts after rename-* and before
-- retire-*, so the renames happen first and this fills whatever is still short.
--
-- Exported from the live rows as they stand. Guarded on the key, so on
-- production this finds everything already present and does nothing - it is a
-- fresh environment that needs it.

INSERT OR IGNORE INTO psionic_powers
  (name, category, isp, isp_note, range, duration, saving_throw, description, min_tier, source, source_book)
VALUES
  ('Astral Projection', 'Sensitive', 8, NULL, 'Self', '5 minutes per level of experience.', NULL, 'Through intense concentration/meditation (4D4 minutes of preparation) the psychic can free his mind, or inner self, from his physical body. This psychic inner self is the astral body, a whitish, transparent, ghostly image of the character''s physical form. A long silver thread or cord connects the astral body with its physical self. If the cord is severed the character is likely to die of sudden shock as body and soul are torn asunder. There is only a 30% chance the astral self can locate its physical body without the silver umbilical cord (roll best 2 out of 3). The physical body lapses into a coma-like trance when the astral self has left it, completely helpless and catatonic. Hazards: if the physical body is killed, the astral body is forever lost and will die within six hours; if the astral body gets lost or captured in the astral plane, the physical body will begin to waste away and die (one minute of our time equals one week in the astral plane); the astral body is vulnerable to psychic attacks and attacks from ghosts, entities and creatures of the astral plane. There are two levels: coexistence in the material world (visible only to psychics, children under 13, animals, and most supernatural creatures, granting flight at mach one/670mph, see the invisible, pass through solid objects, impervious to physical harm, but unable to communicate except via telepathy or empathy), and travel into the astral plane itself, a dimension of swirling white with no up or down, where time is greatly distorted (a week there is about one minute here), and where hostile entities and elemental creatures dwell. The silver cord has Astral S.D.C. equal to two times the person''s physical hit points and S.D.C. combined, and is difficult to hit (attackers are -6 to strike); the astral body itself has the same Astral S.D.C. total. Exorcism will force the astral traveler to leave the area (400ft radius) and not return for 24 hours. To return from the astral plane, roll percentile dice (up to three times per melee) on a table: 1-30 Hopelessly Lost, 31-50 Uncertain/Confused, 51-76 Fairly certain, 77-00 Definitely certain (success). Traveling with a partner is safer since one can lead the other back. On the material plane, the astral self can find its physical body if moved or hidden with 60% efficiency (once per melee).', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Bio-Manipulation (the evil eye)', 'Super', 10, NULL, '160ft/48.8m', '4-16 minutes (roll 4D4)', 'Standard', 'Induces physical trauma to the nervous system of others. Seven effects, each affecting one person per attack, costing 10 I.S.P. each, extendable 4-16 (4D4) minutes per additional 6 I.S.P.: Blind (-9 strike/parry/dodge); Deafness (-6 parry/dodge from behind, -3 strike/parry/dodge others, loses initiative); Mute (-2 strike/parry/dodge first melee only); Pain (-6 strike/parry/dodge, 1 hit point damage per minute affected); Paralysis (completely incapacitated); Stun (forfeit one attack, speed halved, -4 strike/parry/dodge); Tissue Manipulation (itching or hot/cold sensations, -1 strike/parry/dodge). A successful standard save negates the effect entirely.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Bio-Regeneration', 'Healing', 6, NULL, 'Self', 'Permanent', 'None', 'This the ability to mentally heal oneself of disease, poison, or physical damage. Unfortunately, this ability is limited to the healing of oneself and can not help others. The process requires one full minute of concentration, meaning the character can not use any other psionic power during that time. Bio-Regeneration does not restore missing limbs, but does restore 2-12 (2D6) hit points, or 3-18 (3D6) physical S.D.C. points per melee. In addition, when cuts and scrapes are healed through bio-regeneration there is NO scarring. The psionic can regenerate as often as once every other minute.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Bio-Regeneration (Super)', 'Super', 20, NULL, 'Self', 'Permanent', NULL, 'The psionic directs psychic energies to immediate self healing. Must concentrate for one full minute while the body instantly heals: 4D6 hit points and 4D6 S.D.C. points are simultaneously restored at the end of 60 seconds, with no scarring.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Detect Psionics', 'Healing', 6, NULL, 'Self, sensing range is 30 feet (9 m) per level of experience.', 'One minute per level of experience.', NULL, 'This is a mental probe that will indicate the presence of psionic energy within the immediate area. The probe can not be used to pinpoint the exact location of psychic energy nor the level of power other than a vague sense of weak, medium, or powerful, but will indicate whether an individual is psychic by directing the probe at a specific person (does not reveal the type or strength of the person''s powers other than low, medium, high). It will also indicate whether a group mind block is in effect and if a person is psionically possessed.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Ectoplasm', 'Physical', 6, NULL, '40ft + 5ft per level of experience(12.2+1.5m).', '4 minutes (16 melees) per level of experience.', NULL, 'Vapor costs 6 I.S.P., Solid costs 12 I.S.P. This mystifying ability enables the psychic to create a slightly luminous, vapor-like substance that is exuded from the pores. Ectoplasm has two forms: an invisible vapor and a luminous, solid state. The vapor is a sort of floating, probing finger that can snuff out candles, open doors, knock over or pick up small objects (weighing under 9 ounces/255 grams), tap somebody on the shoulder, rustle leaves and knock on a door. The ectoplasmic vapor can be seen only by its creator, psychics and supernatural beings who can see the invisible, or with infrared optic systems. Ectoplasm, although an invisible vapor, has physical properties, which means it can not go through walls or other solid obstructions. The solid state of ectoplasm can be a startling sight, for it is clearly visible to everyone. In this form the ectoplasm can be shaped into an extra limb, such as a hand or arm and hand, or tentacle or even a foot. The appendage can hover, float, levitate and fly (at a speed of 18) and can carry, lift or hold up to 40lbs/18kg, but can not squeeze through tiny openings. Ecto-Combat: Vapor and solid get an automatic dodge against all attacks, +5 to dodge, +1 to parry, +1 to strike; Astral S.D.C. is 40 plus one hit point. If the ectoplasm is destroyed the creator takes one hit point and 10 S.D.C. of physical damage. Vapor inflicts no physical damage, solid ectoplasm inflicts one point of damage in combat or by weapon. Attacks or actions per melee equal creator''s. Sunlight or bright artificial light (250 watts) reduces range to half. One full melee is required to create an appendage, half a melee to withdraw it.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Empathic Transmission', 'Super', 6, NULL, '60ft (18.2m)', '2D6 minutes (2 to 12 minutes)', 'Standard', 'Instills a powerful emotion into another living creature; only one creature per attack. Effects include: Despair/Sorrow (50% chance of surrender/fleeing, -2 parry/dodge); Confusion (-3 strike/parry/dodge, loses initiative); Fear (-3 strike/parry/dodge, 66% chance to flee); Hate/Anger (60% chance to attack/harm/betray disliked targets, +1 strike, -1 parry/dodge); Love/Peacefulness (60% chance hostile opponents reconsider actions); Trust (victims believe what the psionic tells them while under influence; life-threatening suggestions get an additional save at +3).', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Exorcism', 'Healing', 10, NULL, 'Immediate area, touch or within 8ft (2.4m).', 'Instant, if successful.', NULL, 'The healer can perform a rite of exorcism that uses psychic energy to expel the loathsome being from its mortal, host body. A completely successful exorcism will free the victim of the supernatural force that controls him and send it back to its own non-earthly world. A partially successful exorcism will drive the evil force out of the possessed person or animal, but does not send the damnable thing back to its own dimension. Thus, it can try to possess the healer or flee to wander the Earth in search of new victims. An exorcism can only be used on living persons or animals whose bodies are inhabited by a supernatural entity or creature. Roll to determine success for an exorcism at the end of the time period. First, roll to see if the being has been expelled from its victim''s body. Success ratio: 28% + 7% per each additional level of experience. Second, roll to see if the thing is forced back into its own dimension. Success Ratio: 21%+ 7% per each additional level of experience. A failed roll means the creature can remain in our dimension, but it must leave the area and can not possess the same individual for at least six months. Note: The chance of a successful exorcism on a nega-psychic is reduced by half, as is the success ratio for sending the being back to its own dimension. The same is true of some of the more powerful supernatural beings. During the exorcism the possessing force can use whatever powers it may have, as well as physical attacks or any special psychic abilities of its host body. Fortunately, the rite of exorcism weakens the creature, reducing its number of attacks per melee by half. It is wise to always have one or more assistants to help defend against the being''s attacks and actions. Sedating the physical host body will immobilize it, but will not prevent psychic attacks or the creature''s use of its natural powers. Too many assistants or spectators can be a liability, for the creature may attempt to flee by possessing one of them. An exorcism can be attempted on the same individual as often as the healer desires.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Group Mind Block', 'Super', 22, NULL, '120 feet (36.6 m)', '10 minutes per level of experience', NULL, 'The master psionic can instantly erect a mental barrier or mind block protecting himself and those around him within a 120 foot area, working like the individual mind block power, preventing psionic probes and telepathic/empathic communication. Everyone in the area is automatically blocked, though the effect is not detectable except via a detect psionics roll.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Hypnotic Suggestion', 'Super', 6, NULL, '12ft/3.6m, with eye contact', 'Varies with each circumstance and subject; rarely more than a few hours maximum', 'Standard', 'A psychically boosted form of hypnosis limited to relaxing/calming, inducing light sleep, aiding focus/memory, and implanting subtle ideas via comments that must be simple and clear. Can also make the victim imagine sounds and images if the savings throw is failed. Costs 6 I.S.P. per idea or attempt to implant an idea.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Impervious to Poison/Toxin', 'Physical', 4, NULL, 'Self', '2 minutes (8 melees)', NULL, 'The character can negate the full effects of poisons and toxic chemicals which he has ingested (eaten or drank) or introduced into the bloodstream, as long as he/she has advance knowledge of its deadly properties. A poison, toxin, or drug which has been unknowingly inflicted (and starting to take effect) can be negated too, but will do half damage or effect before it can be completely negated. Bonuses: Identify poisons ' || char(8212) || ' 30% + 4% per level of experience; +2 to save vs poisons and drugs.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Increased Healing', 'Healing', 10, NULL, 'Touch or within 3ft (0.9m).', '2D4 days.', NULL, 'The healer is able to stimulate another person''s healing energies, dramatically increasing one''s recuperative powers. Hit points and S.D.C. recovery are double the normal professional treatment rate.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Levitation', 'Physical', 2, NULL, 'Up to 60ft/18.3m away.', '2 minutes per level of experience.', 'None', 'Small objects cost 2 I.S.P., medium 6 I.S.P., large 6 plus 1 per every 10 lbs over 20 lbs. Levitation is a limited form of telekinesis that can raise an object (or even a person) straight up into the air and suspend it there (hover). Small objects weighing two pounds (0.9kg) or less are the easiest to levitate. Maximum height is 8ft (2.4m) plus one foot (0.3m) per each level of experience. Medium size objects weighing 3 to 20 pounds (1.4 to 9.1kg) are more difficult, requiring greater concentration. Maximum height is 6ft (1.8m) plus one foot (0.3m) per level of experience. Large objects or people weighing over 20lbs cost 6 I.S.P. plus 1 I.S.P. for every 10 lbs beyond 20. Thus, a 125lb weight (56.7kg) would require 17 I.S.P. to raise it into the air. Maximum height is 4ft (1.2m) plus one foot (0.3m) per level of experience.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Mentally Possess Others', 'Super', 30, NULL, 'Touch', '5 minutes per level of experience', NULL, 'The Mind Melter completely takes over and controls another person''s body; his psychic essence transfers into the victim''s body, retaining his own knowledge and identity but cannot read the victim''s mind or memories, controlling only the physical body. The victim goes into a trance and remembers nothing afterward, while the psionic''s own body falls into a coma-like state, vulnerable to attack. The possessing character can return to his own body at any time regardless of distance.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Mind Block Auto-Defense', 'Super', 14, 'special - see description', 'Self', 'Special', NULL, 'The moment the psychic is mind probed, a personal mind block automatically snaps into place, alerting the psionic that he is being probed via telepathy or empathy. The character must consciously lower the shield to allow the probe. The character permanently gives up 14 I.S.P. when this power is selected, but the mind block engages automatically at no additional I.S.P. cost.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Mind Bond', 'Super', 10, NULL, 'Touch', 'Special', 'Standard', 'Creates an instant mind link between the psionic and victim; each learns EVERYTHING about the other, including skills, secret identities, and phobias. Memory is complete for only 3-12 hours (3D4), after which characters must roll under 15% to recall details; after one month all memories disappear. Skills and skill bonuses are temporarily absorbed, but physical attributes are not gained. Bonding with an alien or extremely disturbed mind can cause a permanent insanity (roll percentile: 1-40 none, 41-80 phobia, 81-90 affective disorder, 91-00 neurosis).', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Mind Wipe', 'Super', 10, '10; 50 for permanent', 'Touch', 'Special', 'Standard', 'To mind wipe an intelligent creature, the psionic must make physical contact with the victim''s temples and erase any past event, knowledge or skill via verbal suggestion; process takes about three minutes. Loss of memory is temporary, lasting 1D4 days for every 10 I.S.P. expended; can be permanently erased by exerting 50 I.S.P. at once, or wiped completely blank by expending 50 I.S.P. plus four permanent Mental Endurance points (an extremely grueling process, with the M.E. loss permanent even if the victim saves).', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Nightvision', 'Physical', 4, NULL, 'Self, visual range about 600 feet (183 m)', '10 minutes per level of experience.', NULL, 'The psionic can adjust his visual capabilities through a form of bio-manipulation. The eyes are made to become much more light sensitive and basically works on the same principles of mechanical light amplification. The eyes simply amplify existing light, such as candlelight or star and moonlight, to see clearly. There must be some source of light to see (can not see in total darkness). Note: If suddenly exposed to light brighter than a single candle, the psychic will be temporarily blinded for 3D4 melees. The nightvision power can also be used to change one''s vision to polarized sight, reducing glare as would a pair of polarized sun glasses.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Object Read (Psychometry)', 'Sensitive', 6, NULL, 'Touch', 'Varies; usually about 2D6 minutes.', 'None', 'This uncanny ability enables the psychic sensitive to receive impressions and images from an object regarding its use, history and last owner, by holding the object and concentrating. Impressions include: general alignment of its last owner, general emotional state of mind, the object''s general purpose, whether the last owner is living or dead, and whether the item has been used with/by magic or supernatural forces; also indicates whether the item is currently enchanted or contains a supernatural force/entity. If the item is possessed, an object read makes the reader totally vulnerable to psychic attack (no bonuses to save). Images: brief snippets of past events involving the object and its owner, including approximate age, height, weight, build, race, sex, occupation, hair, special features, and a special traumatic or important event. Base Skill: Impressions 56% +2% per level; Images 48% +2% per level; Present 38% +2% per level. Roll separately for impressions and images; a roll higher than base skill means failure. The present can not be seen unless the psychic succeeded on impressions or images, and costs an additional 4 I.S.P. with no guarantee of success. Once an object has been read it can not be read again by the same psychic; further attempts on other items cost 6 I.S.P. each.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('P.P.E. Shield', 'Super', 10, NULL, 'Self', '6 minutes per level of experience', NULL, 'A psionic defense used to prevent P.P.E. vampires, psi-stalkers, and mages from siphoning off one''s psychic energy. Works similarly to a mind block, but prevents others from draining one''s P.P.E.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Psi-Shield', 'Super', 30, NULL, 'Self', '5 minutes per level of experience', NULL, 'A companion power to the psi-sword in which the psionic creates a mega-damage shield out of thin air, able to parry all hand-to-hand combat attacks including from robots, power armor, and magic, but not energy blasts or projectiles. Shield M.D.C. is 80.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Psi-Sword', 'Super', 30, NULL, 'Self', '5 minutes per level of experience', NULL, 'A mega-damage energy weapon the psychic mentally wills into existence, appearing as a shimmering blade whose shape reflects its creator''s personality; can be created in about 15 seconds (one melee) and maintained for 5 minutes per level of experience. If the psychic is knocked unconscious the weapon disappears; it can also be willingly dispelled (costing another 30 I.S.P. to recreate). Damage: 4D6 M.D. at level three (cannot be selected until level three), adding 2D6 at levels four, seven, nine, twelve, and fifteen. Damage can be adjusted at will in increments of 1D6 M.D. from a minimum of 2D6 up to the character''s current maximum.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Psychic Diagnosis', 'Healing', 4, NULL, 'Touch or within 3ft (0.9m).', 'Immediate knowledge.', 'None; except for the nega-psychic, standard.', 'The psychic healer can sense physical pain, damage, disease and possession with absolute clarity. This pinpoint accuracy enables the character to suggest treatment or to conduct psychic surgery.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Psychic Purification', 'Healing', 8, NULL, 'Touch', 'Immediate', 'None; except for the nega-psychic, standard.', 'The healer can use his abilities to slow a person''s metabolism and destroy chemicals, drugs, poisons, and toxins in the body. The effects of the drugs/impurities are immediately halted at the beginning of the meditation, and completely destroyed/negated by its end. Damage sustained prior to the psychic''s intervention still exists.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Psychic Surgery', 'Healing', 14, NULL, 'Touch', 'Varies with injury.', NULL, 'Psychic surgery is used to repair broken bones, internal injuries, the removal of foreign objects (bullets, etc.), or when a character has suffered so much damage that he or she has lapsed into a coma (zero or less hit points). The recovery from a coma (near death) is equal to treatment from a hospital, 1-66%, when psychic surgery is used. Note that there is absolutely no scarring from psychic surgery and minimal pain (no pain if the deaden pain psi-ability is used). No tools are needed, only the psychic''s hands. Note: A psychic diagnosis must be made before surgery is possible.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Resist Hunger', 'Physical', 2, NULL, 'Self', '6 hours', NULL, 'Another mind over matter discipline that subdues any feeling of hunger, allowing the character to function at full effectiveness without nourishment. It is important to point out that while the psi-power maintains full operations, the body is still suffering from malnutrition and starvation. Loses 3lbs of weight per day. Note: A psychic can survive up to 60 days, functioning as normal, without any food by continually using resist hunger. On day 61 the character will lapse into a coma. Under this extreme condition, 60 days of food deprivation while still fully active physically, the character is ' || char(8212) || '20% to save vs coma/death.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Resist Thirst', 'Physical', 6, NULL, 'Self', '6 hours', NULL, 'This ability is identical to the resist hunger psi-power except it applies to the consumption of water. It does not negate the long-range damage from dehydration.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('See The Invisible', 'Sensitive', 4, NULL, '120ft/36m distances.', '1 minute per each level of experience.', 'None', 'The character can see forces, objects and creatures which can turn invisible or are naturally invisible. Even if the creatures have no form per se, the psychic will be able to discern the vaporous image or energy sphere which is the being. This includes ghosts, entities and the astral body.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Sense Evil', 'Sensitive', 2, NULL, '140ft/42.7m area.', '2 minutes (8 melees) per level of experience.', 'None', 'This psi-power is a much more refined ability to feel the presence of evil. All supernatural creatures radiate their alignment, good or evil. A psychic sensitive will automatically feel supernatural evil without...', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Sense Magic', 'Sensitive', 3, NULL, '120ft/36m area', '2 minutes per level of experience', 'None', 'The psychic can feel magic energy, tell whether it is near (within 20ft/6.1m) or far (up to 120ft/36m away) and follow the emanations to pinpoint their source as a particular place, room, person or object. Invisible, magical supernatural creatures or objects can only be traced to a general area. The psychic can sense whether an object has magic powers, if a person or item is enchanted/under a spell, when magic is being used within the area, and when a person is casting a spell.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Speed Reading', 'Sensitive', 2, NULL, 'Self', '3 minutes per level of experience', NULL, 'The ability to read and comprehend the written word extremely quickly. Speed of reading is 30 pages per minute/4 melees. The psychic retains information normally. Highly technical texts reduce speed reading by half (15 pages per minute) and may require two readings.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Telekinesis', 'Physical', 3, NULL, 'Up to 60ft (18.3m) away.', '2 minutes per level of experience.', NULL, 'Small objects cost 3 I.S.P., medium ' || char(8212) || ' 8 I.S.P., large (over 20lbs) ' || char(8212) || ' 8+1 per every 10 lbs of weight. Telekinesis is the ability to move objects without any other means than directed psychic energy. The character can make an object hop, fall, roll, rise into the air, suspend it there (hover) or make it fly across the room. In order to move an object by telekinesis, the item must be clearly visible, within the psychic''s range (60ft/18.3m) and the point of focus. Each telekinetic feat counts as one of the character''s physical attacks. The total number of telekinetic attacks is equal to the character''s number of physical attacks per melee; usually 3 or 4. It is easiest to move or hurl small objects weighing two pounds (0.9kg) or less. Maximum height or distance is 60ft (18.3m). Medium size objects weighing 3 to 20 pounds (1.4 to 9.1kg) are more difficult to manipulate. Maximum height or distance is reduced by half ' || char(8212) || ' 30 feet (9.1m). Large or heavy objects weighing over 20lbs are the most difficult to maneuver, reducing maximum height and distance to 15ft (4.6m). I.S.P. cost for large, heavy objects is 8 I.S.P. for the first 20lbs (9.1kg) plus one I.S.P. for each additional 10 lbs (4.5kg) of weight. This means it would cost 19 I.S.P. to move a 125lb (56.7kg) weight.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Telekinesis (Super)', 'Super', 10, NULL, '100 feet (30.5 m) per level of experience', '2 minutes per level of experience', NULL, 'Same as the Physical category telekinesis power but greatly enhanced with increased range, weight capacity, and damage. Costs 10 I.S.P. to lift/move/hurl an object weighing 100 lbs (45 kg), plus 10 I.S.P. per each additional 100 lbs. Damage: 1D4x10 S.D.C. per 100 lbs of weight (100 S.D.C. = 1 M.D. point). Can manipulate as many objects as levels of experience, as long as combined weight doesn''t exceed total capacity. Combat bonuses same as non-super telekinetic power.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Telekinetic Force Field', 'Super', 30, NULL, 'Self or 40 feet (12.2 m) per level of experience', '10 minutes per level of experience', NULL, 'Instantly erects a force field around the psychic or others; if used to parry, the psionic must roll a successful parry to create the field before the attack strikes. Field can encircle just its creator or up to a 10 foot area per level of experience, created within line of vision, smallest field about 3 feet. Field is mega-damage with 25 M.D.C. per level of experience; multiple fields can be created as I.S.P. allows. Fields remain until destroyed, dispelled, duration expires, or the creator is rendered unconscious/killed. The force field cannot be moved once created and is airtight.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Telemechanics', 'Super', 10, NULL, 'Touch or 5ft away (1.5m)', '10 minutes plus 2 minutes per level of psionic', 'None', 'Allows the psionic to mentally communicate with and understand machines, a combination of object read and telepathy applied only to mechanical devices. By touching a non-artificially intelligent machine, the psionic gains instant, temporary complete knowledge of how it operates, equal to an 80% scholastic skill level. When touching an artificially intelligent machine (e.g., computers), the psionic can also communicate with it telepathically, tapping its memory bank directly, with skill knowledge equal to 88% proficiency.', NULL, 'import', 'Rifts Ultimate Edition'),
  ('Total Recall', 'Sensitive', 2, NULL, 'Self', 'Permanent', NULL, 'The character remembers every word he reads; specific blocks of information can be recalled in perfect detail at will for 3 I.S.P. per block. If all I.S.P. have been expended, memory is fuzzy: roll percentile: 1-50 remembered in full detail; 51-80 details forgotten but essence clear; 81-00 only basic concepts recalled, no details.', NULL, 'import', 'Rifts Ultimate Edition');

-- Read the result back rather than trusting the exit code.
SELECT count(*) AS psionic_powers_total FROM psionic_powers;

INSERT INTO data_script_runs (filename) VALUES ('restore-psionics-missing-from-repo.sql');
